//go:build dbox2d_simd && !dbox2d_fixed && goexperiment.simd && go1.27 && amd64

package b2

// solveContactsWideAVX2 runs solveContactsTaskWide over n constraints in
// assembly generated by tools/asmgen. It keeps the Go operation order, so
// the results are identical; the Go version stays as the reference and as
// the path for other builds.
//
//go:noescape
func solveContactsWideAVX2(c *contactConstraintWide, n int, states *bodyState, invH float32)

// solveContactsTaskWideAsm is the amd64 relax stage.
func solveContactsTaskWideAsm(startIndex, endIndex int, context *stepContext, colorIndex int) {
	if startIndex >= endIndex {
		return
	}
	constraints := context.graph.colors[colorIndex].contactConstraintsWide[startIndex:endIndex]
	solveContactsWideAVX2(&constraints[0], len(constraints), &context.states[0], laneScalarFromQ(context.invH))
}

//go:noescape
func warmStartContactsWideAVX2(c *contactConstraintWide, n int, states *bodyState)

//go:noescape
func pushContactsWideAVX2(c *contactConstraintWide, n int, states *bodyState, invH, negContactSpeed, one float32)

// warmStartContactsTaskWideAsm is the amd64 warm start stage.
func warmStartContactsTaskWideAsm(startIndex, endIndex int, context *stepContext, colorIndex int) {
	if startIndex >= endIndex {
		return
	}
	constraints := context.graph.colors[colorIndex].contactConstraintsWide[startIndex:endIndex]
	warmStartContactsWideAVX2(&constraints[0], len(constraints), &context.states[0])
}

// pushContactsTaskWideAsm is the amd64 push stage. The contact speed is
// negated as laneW.Neg does, by a multiply with -1.
func pushContactsTaskWideAsm(startIndex, endIndex int, context *stepContext, colorIndex int) {
	if startIndex >= endIndex {
		return
	}
	constraints := context.graph.colors[colorIndex].contactConstraintsWide[startIndex:endIndex]
	negOne := laneScalar(-1)
	negContactSpeed := laneScalarFromQ(context.world.contactSpeed) * negOne
	pushContactsWideAVX2(&constraints[0], len(constraints), &context.states[0],
		laneScalarFromQ(context.invH), negContactSpeed, laneScalarFromQ(QOne()))
}
